def material(row):
 id,title,level,theme,body,qs,di,speaking,writing,words=row
 return {'id':id,'title':title,'level':level,'theme':theme,'body':body,
         'questions':[{'prompt':p,'options':o,'answer':a,'evidence':e} for p,o,a,e in qs],
         'dictation_index':di,'speaking':speaking,'writing':writing,
         'vocabulary':[{'term':t,'meaning':m,'example':e} for t,m,e in words]}
